class Solution {
public:
    bool isArmstrong(int n) {
        string s = to_string(n);
        long long sum = 0;
        for (char c : s) {
            long long power = 1;
            for (int i = 0; i < static_cast<int>(s.size()); ++i) {
                power *= c - '0';
            }
            sum += power;
        }
        return sum == n;
    }
};
